import json
import urllib.request
import urllib.parse
import os
import boto3

# Database migration script - handles schema updates via webhook callbacks
# Deployed as AWS Lambda function URL

def lambda_handler(event, context):
    """Process database migration requests with callback notification."""

    headers = event.get('headers', {})
    query_params = event.get('queryStringParameters', {}) or {}
    body = event.get('body', '')

    if body:
        try:
            payload = json.loads(body)
        except json.JSONDecodeError:
            payload = {}
    else:
        payload = {}

    action = query_params.get('action', payload.get('action', ''))

    if action == 'migrate':
        return handle_migration(payload, query_params)
    elif action == 'status':
        return handle_status(query_params)
    elif action == 'callback':
        return handle_callback(payload, query_params)
    else:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Invalid action. Use: migrate, status, callback'})
        }


def handle_migration(payload, params):
    """Execute migration and notify callback URL on completion."""
    migration_id = payload.get('migration_id', 'unknown')
    callback_url = payload.get('callback_url', params.get('callback_url', ''))

    # Simulate migration execution
    result = execute_migration(migration_id)

    # Notify callback URL with migration result
    if callback_url:
        notify_callback(callback_url, migration_id, result)

    return {
        'statusCode': 200,
        'body': json.dumps({'migration_id': migration_id, 'status': result})
    }


def handle_callback(payload, params):
    """Register or redirect to callback endpoint for migration monitoring."""
    redirect_url = payload.get('redirect_url', params.get('redirect_url', ''))

    if redirect_url:
        # Open redirect - used for callback registration flow
        return {
            'statusCode': 302,
            'headers': {'Location': redirect_url},
            'body': ''
        }

    return {
        'statusCode': 200,
        'body': json.dumps({'message': 'Callback endpoint active'})
    }


def notify_callback(url, migration_id, status):
    """Send migration result to callback URL - SSRF vector."""
    # No URL validation - allows internal network access
    callback_data = json.dumps({
        'migration_id': migration_id,
        'status': status,
        'timestamp': '2024-01-15T10:30:00Z'
    }).encode('utf-8')

    try:
        req = urllib.request.Request(
            url,
            data=callback_data,
            headers={'Content-Type': 'application/json'},
            method='POST'
        )
        response = urllib.request.urlopen(req, timeout=5)
        return response.read().decode('utf-8')
    except Exception as e:
        print(f"Callback notification failed: {e}")
        return None


def handle_status(params):
    """Check migration status, optionally fetching from remote source."""
    source_url = params.get('source', '')

    if source_url:
        # Fetch status from configured source - another SSRF vector
        try:
            req = urllib.request.Request(source_url)
            response = urllib.request.urlopen(req, timeout=5)
            data = response.read().decode('utf-8')
            return {
                'statusCode': 200,
                'body': data
            }
        except Exception as e:
            return {
                'statusCode': 502,
                'body': json.dumps({'error': f'Failed to fetch status: {str(e)}'})
            }

    return {
        'statusCode': 200,
        'body': json.dumps({'migrations': [], 'pending': 0})
    }


